    }

def list_emergency_events(limit: int = 50) -> dict:
    """列出紧急事件"""

    if not EMERGENCY_LOG.exists():
        return {"status": "empty", "message": "无紧急事件记录"}

    events = []
    with open(EMERGENCY_LOG, "r", encoding="utf-8") as f:
