    return {
        "status": "success",
        "count": len(events),
        "events": events[:limit]
    }

def clear_stop_flag():
    """清除停止标志 (管理员功能)"""
    if STOP_FLAG.exists():
        STOP_FLAG.unlink()

def main():
    if len(sys.argv) < 2:
        # 测试模式
        print("=" * 70)
        print("立即停止机制 v1.0")
        print("=" * 70)

        # 检查当前状态
        status = check_stop_status()
