            "step_id": step_id,
            "action": "CONTINUE"
        }

    def workflow_completion_check(self, completion_percentage: float, compliance: bool) -> dict:
        """工作流完成检查 (自动决定奖励或惩罚)"""

        from pathlib import Path

        if completion_percentage == 100 and compliance:
